-- Studio Manager Fase 1. Applicare UNA volta su D1 prima del deploy.
CREATE TABLE IF NOT EXISTS sm_disciplines(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sm_specialists(id TEXT PRIMARY KEY,name TEXT NOT NULL,discipline_id TEXT REFERENCES sm_disciplines(id),email TEXT,phone TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sm_services(id TEXT PRIMARY KEY,name TEXT NOT NULL,specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),duration INTEGER NOT NULL CHECK(duration BETWEEN 5 AND 480),price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sm_patients(id TEXT PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT NOT NULL,birth_date TEXT,cf TEXT,email TEXT,phone TEXT,address TEXT,guardian_name TEXT,guardian_phone TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_sm_patient_cf ON sm_patients(upper(cf)) WHERE cf IS NOT NULL AND cf<>'';
CREATE INDEX IF NOT EXISTS idx_sm_patients_name ON sm_patients(last_name,first_name);
CREATE TABLE IF NOT EXISTS sm_assignments(patient_id TEXT NOT NULL REFERENCES sm_patients(id),specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),PRIMARY KEY(patient_id,specialist_id));
CREATE TABLE IF NOT EXISTS sm_schedules(id TEXT PRIMARY KEY,specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),start_time TEXT NOT NULL,end_time TEXT NOT NULL,valid_from TEXT,valid_until TEXT, CHECK(start_time<end_time));
CREATE INDEX IF NOT EXISTS idx_sm_schedules ON sm_schedules(specialist_id,weekday);
CREATE TABLE IF NOT EXISTS sm_blocks(id TEXT PRIMARY KEY,specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL,reason TEXT, CHECK(start_at<end_at));
CREATE TABLE IF NOT EXISTS sm_appointments(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES sm_patients(id),specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),service_id TEXT REFERENCES sm_services(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'prenotato' CHECK(status IN ('prenotato','confermato','arrivato','in_visita','concluso','assente','annullato')),price_cents INTEGER NOT NULL DEFAULT 0,notes TEXT,recurrence_id TEXT,cancel_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(start_at<end_at));
CREATE INDEX IF NOT EXISTS idx_sm_apt_specialist_time ON sm_appointments(specialist_id,start_at,end_at,status);
CREATE INDEX IF NOT EXISTS idx_sm_apt_patient ON sm_appointments(patient_id,start_at);
CREATE TABLE IF NOT EXISTS sm_clinical_notes(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES sm_patients(id),specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),appointment_id TEXT REFERENCES sm_appointments(id),subject TEXT NOT NULL,anamnesis TEXT,assessment TEXT,treatment TEXT,free_text TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sm_shares(patient_id TEXT NOT NULL REFERENCES sm_patients(id),owner_specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),recipient_specialist_id TEXT NOT NULL REFERENCES sm_specialists(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(patient_id,owner_specialist_id,recipient_specialist_id));
CREATE TABLE IF NOT EXISTS sm_audit(id TEXT PRIMARY KEY,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,detail TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sm_documents(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES sm_patients(id),specialist_id TEXT REFERENCES sm_specialists(id),object_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,mime TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sm_documents_patient ON sm_documents(patient_id,created_at);
